# returns on capital, filed/XBRL figures (XBRL checked to the filed FY2025 statements); impairments kept in [E5-33]
OI={2011:67.5,2012:147.6,2013:111.3,2014:-62.4,2015:79.8,2016:97.9,2017:104.2,2018:118.7,2019:-144.3,2020:69.7,2021:141.5,2022:153.7,2023:125.1,2024:151.9,2025:-44.4}
IMP={2014:16.8,2019:247.4,2025:90.3}  # operating-line impairments as filed in CF (2014 continuing; coal mining loss in disc ops)
EQ={2010:429.3,2011:559.9,2012:574.9,2013:832.3,2014:705.4,2015:622.8,2016:639.9,2017:659.6,2018:682.7,2019:518.4,2020:500.9,2021:535.4,2022:622.7,2023:645.5,2024:711.0,2025:626.1}
DEBT={2010:0,2011:726.4,2012:723.4,2013:689.1,2014:633.5,2015:998.8,2016:854.1,2017:863.7,2018:838.4,2019:782.9,2020:676.9,2021:613.6,2022:532.2,2023:490.3,2024:492.3,2025:685.5}
CASH={2010:40.1,2011:127.5,2012:239.2,2013:233.6,2014:139.0,2015:123.4,2016:134.0,2017:120.2,2018:145.7,2019:97.1,2020:48.4,2021:63.8,2022:90.0,2023:140.1,2024:189.6,2025:88.7}
NIatt={2011:60.6,2012:98.8,2013:25.0,2014:-126.1,2015:-22.0,2016:14.4,2017:122.4,2018:26.2,2019:-152.3,2020:3.7,2021:43.4,2022:100.7,2023:57.5,2024:95.9,2025:-44.2}
SE={2010:369.5,2011:525.5,2012:539.1,2013:557.4,2014:431.7,2015:289.9,2016:311.1,2017:426.2,2018:463.1,2019:491.6,2020:469.0,2021:498.1,2022:585.6,2023:614.2,2024:680.2,2025:597.3}
REV={2011:1538.9,2012:1864.7,2013:1647.7,2014:1503.8,2015:1362.7,2016:1223.3,2017:1331.5,2018:1450.9,2019:1600.3,2020:1333.0,2021:1456.0,2022:1972.5,2023:2063.2,2024:1935.4,2025:1837.3}
print('FY | rev | op inc | op inc ex-impairment | net capital avg | pre-tax ROC | ex-imp | NI attrib | avg SXC equity | ROE')
t=[0,0,0,0,0]
for y in range(2012,2026):
    cap=((EQ[y]+DEBT[y]-CASH[y])+(EQ[y-1]+DEBT[y-1]-CASH[y-1]))/2
    se=(SE[y]+SE[y-1])/2
    x=OI[y]+IMP.get(y,0)
    t[0]+=OI[y];t[1]+=x;t[2]+=cap;t[3]+=NIatt[y];t[4]+=se
    print(f'{y} | {REV[y]:.1f} | {OI[y]:.1f} | {x:.1f} | {cap:.1f} | {100*OI[y]/cap:.1f}% | {100*x/cap:.1f}% | {NIatt[y]:.1f} | {se:.1f} | {100*NIatt[y]/se:.1f}%')
print(f'AGGREGATE 2012-2025: pre-tax ROC {100*t[0]/t[2]:.1f}% (ex-impairment {100*t[1]/t[2]:.1f}%); ROE on SXC equity {100*t[3]/t[4]:.1f}%; op margin {100*t[0]/sum(REV[y] for y in range(2012,2026)):.1f}%')
